import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';
import { cn } from '@loomui/ui/utils';
import { UI_BREADCRUMB_GENERATED } from './breadcrumb';
import { UiIconSvg } from '@loomui/ui/icon';
import { UiElementHost } from '@loomui/ui/utils';

/** <li uiBreadcrumbSeparator></li> — renders a chevron (mirrored in RTL). Pass custom content to replace it. */
@Component({
  selector: 'li[uiBreadcrumbSeparator], ui-breadcrumb-separator', hostDirectives: [UiElementHost],
  imports: [UiIconSvg],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    role: 'presentation',
    'aria-hidden': 'true',
    'data-slot': 'breadcrumb-separator',
    '[attr.class]': 'classes()',
  },
  template: `
    <ng-content>
      <svg uiIcon="chevron-right" class="rtl:rotate-180"></svg>
    </ng-content>
  `,
})
export class UiBreadcrumbSeparator {
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn('[&>svg]:size-3.5 [&>ui-icon]:size-3.5', this.userClass()));
}

/** <span uiBreadcrumbEllipsis></span> — "…" with an sr-only "More" label. */
@Component({
  selector: 'span[uiBreadcrumbEllipsis], ui-breadcrumb-ellipsis', hostDirectives: [UiElementHost],
  imports: [UiIconSvg],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    role: 'presentation',
    'aria-hidden': 'true',
    'data-slot': 'breadcrumb-ellipsis',
    '[attr.class]': 'classes()',
  },
  template: `
    <svg uiIcon="ellipsis"></svg>
    <span class="sr-only">More</span>
  `,
})
export class UiBreadcrumbEllipsis {
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() =>
    cn('flex size-5 items-center justify-center [&>svg]:size-4 [&>ui-icon]:size-4', this.userClass()),
  );
}

export const UI_BREADCRUMB = [...UI_BREADCRUMB_GENERATED, UiBreadcrumbSeparator, UiBreadcrumbEllipsis] as const;

// GENERATED by tools/gen-ui.mjs from docs/evidence/slots/breadcrumb.json.
// Change tools/ui-specs.mjs and regenerate; hand-written parts live in ./breadcrumb.manual.ts.
import { Directive, computed, input } from '@angular/core';
import { cn } from '@loomui/ui/utils';
import { UiElementHost } from '@loomui/ui/utils';

@Directive({
  selector: 'nav[uiBreadcrumb], ui-breadcrumb', hostDirectives: [UiElementHost],
  host: {
    'data-slot': 'breadcrumb',
    'aria-label': 'breadcrumb',
    '[attr.class]': 'classes()',
  },
})
export class UiBreadcrumb {
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn('', this.userClass()));
}

@Directive({
  selector: 'ol[uiBreadcrumbList], ui-breadcrumb-list', hostDirectives: [UiElementHost],
  host: {
    'data-slot': 'breadcrumb-list',
    '[attr.class]': 'classes()',
  },
})
export class UiBreadcrumbList {
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn('flex flex-wrap items-center gap-1.5 text-sm wrap-break-word text-muted-foreground', this.userClass()));
}

@Directive({
  selector: 'li[uiBreadcrumbItem], ui-breadcrumb-item', hostDirectives: [UiElementHost],
  host: {
    'data-slot': 'breadcrumb-item',
    '[attr.class]': 'classes()',
  },
})
export class UiBreadcrumbItem {
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn('inline-flex items-center gap-1', this.userClass()));
}

@Directive({
  selector: 'a[uiBreadcrumbLink], ui-breadcrumb-link', hostDirectives: [UiElementHost],
  host: {
    'data-slot': 'breadcrumb-link',
    '[attr.class]': 'classes()',
  },
})
export class UiBreadcrumbLink {
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn('transition-colors hover:text-foreground', this.userClass()));
}

@Directive({
  selector: 'span[uiBreadcrumbPage], ui-breadcrumb-page', hostDirectives: [UiElementHost],
  host: {
    'data-slot': 'breadcrumb-page',
    'role': 'link',
    'aria-disabled': 'true',
    'aria-current': 'page',
    '[attr.class]': 'classes()',
  },
})
export class UiBreadcrumbPage {
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn('font-normal text-foreground', this.userClass()));
}

export const UI_BREADCRUMB_GENERATED = [UiBreadcrumb, UiBreadcrumbList, UiBreadcrumbItem, UiBreadcrumbLink, UiBreadcrumbPage] as const;
